WITH unpacked AS (SELECT id, customer_id, coupon_codes, items, ship_to.country AS ship_country, ship_to.city AS ship_city, attributes['gift'] AS gift, ARRAY_CONTAINS(coupon_codes, 'BUNDLE') AS used_bundle, SIZE(items) AS num_items FROM carts WHERE customer_id IN (13, 25, 37)) SELECT *, SUM(num_items) OVER (PARTITION BY customer_id, ship_country ORDER BY num_items, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_num_items, SUM(num_items) OVER w_running AS ship_city_sum_num_items, COUNT(num_items) OVER (PARTITION BY ship_country) AS ship_country_count_num_items FROM unpacked WINDOW w_running AS (PARTITION BY ship_city);
